'use strict';

// MODULES //

var isFunction = require( '@stdlib/assert/is-function' );
var isCollection = require( '@stdlib/assert/is-collection' );
var format = require( '@stdlib/string/format' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var validate = require( './validate.js' );
var limit = require( './limit.js' );


// MAIN //

function factory( options, predicate ) {
	var opts;
	var err;
	var f;

	opts = {};
	if ( arguments.length > 1 ) {
		err = validate( opts, options );
		if ( err ) {
			throw err;
		}
		f = predicate;
	} else {
		f = options;
	}
	if ( !isFunction( f ) ) {
		throw new TypeError( format( 'invalid argument. Last argument must be a function. Value: `%s`.', f ) );
	}
	if ( opts.series ) {
		opts.limit = 1;
	} else if ( !opts.limit ) {
		opts.limit = PINF;
	}
	return anyByAsync;

	function anyByAsync( collection, done ) {
		var status;
		var i;

		if ( !isCollection( collection ) ) {
			throw new TypeError( format( 'invalid argument. First argument must be a collection. Value: `%s`.', collection ) );
		}
		if ( !isFunction( done ) ) {
			throw new TypeError( format( 'invalid argument. Last argument must be a function. Value: `%s`.', done ) );
		}

		// Create status object
		status = {
			'nprocessed': 0,
			'ndone': 0,
			'nerrors': 0,
			'total': collection.length,
			'operations': []
		};
		for ( i = 0; i < collection.length; i++ ) {
			status.operations.push({
				'index': i,
				'status': 'pending'
			});
		}

		limit( collection, opts, wrapper, clbk );

		return status;

		function wrapper( value, index, col, next ) {
	// Wrap next to intercept per-element completion
	function onNext( error, bool ) {
		if ( error ) {
			status.nerrors += 1;
			status.operations[ index ].status = 'fail';
		} else {
			status.operations[ index ].status = 'ok';
		}
		status.ndone += 1;
		status.nprocessed += 1;
		next( error, bool );
	}

	// Preserve original argument-count-based dispatch with thisArg context
	if ( f.length === 1 || f.length === 0 ) {
		f.call( opts.thisArg, value, index, col, onNext );
	} else if ( f.length === 2 ) {
		f.call( opts.thisArg, value, onNext );
	} else if ( f.length === 3 ) {
		f.call( opts.thisArg, value, index, onNext );
	} else {
		f.call( opts.thisArg, value, index, col, onNext );
	}
}

		function clbk( error, bool ) {
			if ( error ) {
				return done( error, false );
			}
			done( null, bool );
		}
	}
}


// EXPORTS //

module.exports = factory;
